gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

class GSLFunction:
    def __init__(self, func):
        self.func = func
        self.c_func = self._create_c_function()

    def _create_c_function(self):
        def my_func(x):
            return self.func(x)
        my_func.argtypes = [ctypes.c_double]
        my_func.restype = ctypes.c_double
        return my_func

class CQuadWorkspace:
    def __init__(self, size):
        self.size = size
        self.workspace = gsl.gsl_integration_workspace_alloc(size)

    def __del__(self):
        gsl.gsl_integration_workspace_free(self.workspace)

def integrate_function(func, a, b, epsabs, epsrel, workspace_size):
    try:
        gsl_func = GSLFunction(func).c_func
        workspace = CQuadWorkspace(workspace_size)
        result = ctypes.c_double()
        abserr = ctypes.c_double()
        ncall = ctypes.c_size_t()
        gsl.gsl_integration_cquad(
            gsl_func,
            a,
            b,
            epsabs,
            epsrel,
            workspace.workspace,
            ctypes.byref(result),
            ctypes.byref(abserr),
            ctypes.byref(ncall)
        )
        return {
            "integral": result.value,
            "estimated_abs_error": abserr.value,
            "function_evaluations": ncall.value
        }
    except Exception as e:
        return str(e)

