# Define GSLFunction class
class GSLFunction:
    def __init__(self, func):
        self.func = func
        self.gsl_func = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double)(self.call)

    def call(self, x):
        return self.func(x)

# Define CQuadWorkspace class
class CQuadWorkspace:
    def __init__(self, size):
        self.size = size
        self.workspace = gsl.gsl_integration_workspace_alloc(size)

    def __del__(self):
        if hasattr(self, 'workspace') and self.workspace is not None:
            gsl.gsl_integration_workspace_free(self.workspace)

# Define integrate_function function
def integrate_function(func, a, b, epsabs, epsrel, workspace_size):
    gsl_func = GSLFunction(func).gsl_func
    result = ctypes.c_double(0.0)
    abserr = ctypes.c_double(0.0)
    workspace = CQuadWorkspace(workspace_size).workspace

    status = gsl.gsl_integration_cquad(gsl_func, a, b, epsabs, epsrel,
                                        workspace, ctypes.byref(result),
                                        ctypes.byref(abserr))

    if status != 0:
        raise Exception("GSL integration failed with status: " + str(status))

    return result.value, abserr.value, int(workspace.contents.neval)

