def vector_add(a, b):
    if a.size != b.size:
        raise ValueError("Vectors must be of the same size")
    result = GSLVector([0.0] * a.size)
    gsl.gsl_vector_add(ctypes.byref(a.data), ctypes.byref(b.data), ctypes.c_size_t(a.size))
    return [result.data[i] for i in range(result.size)]

