def fft_factorize(n):
    n = ctypes.c_ulonglong(n)
    factor = ctypes.c_ulonglong(0)
    gsl.gsl_factorize.argtypes = [ctypes.POINTER(ctypes.c_ulonglong)]
    gsl.gsl_factorize.restype = ctypes.c_int
    result = gsl.gsl_factorize(ctypes.byref(factor))
    if result != 0:
        raise ValueError("Factorization failed")
    return prime_factors(n.value), len(prime_factors(n.value))

