        for j in range(cols):
            data[i * cols + j] = matrix[i][j]
    return gsl_matrix(data=data, tda=cols, size1=rows, size2=cols)

def create_gsl_vector_complex(size):
    data = (ctypes.c_double * (size * 2))()
    return gsl_vector_complex(data=data, stride=2, size=size)

def compute_eigenvalues_nonsymm(matrix):
    rows, cols = len(matrix), len(matrix[0])
    if rows != cols:
        raise ValueError("Matrix must be square")

    mat = create_gsl_matrix(matrix)
    evals = create_gsl_vector_complex(rows)
    w = gsl_eigen_nonsymm_workspace(rows)

    gsl.gsl_eigen_nonsymm(mat, evals, ctypes.byref(w))

    eigenvalues = [complex(evals.data[i], evals.data[i+1]) for i in range(0, 2*rows, 2)]

    gsl.gsl_vector_complex_free(evals)
    gsl.gsl_eigen_nonsymm_workspace_free(w)
    gsl.gsl_matrix_free(mat)

    return eigenvalues

