    def __init__(self, data):
        self.data = data
        self.size = len(data)
        self.vector = gsl.gsl_vector_alloc(self.size)
        for i in range(self.size):
            gsl.gsl_vector_set(self.vector, i, ctypes.c_double(self.data[i]))

    def __del__(self):
        gsl.gsl_vector_free(self.vector)

