    if destination_data is None:
        destination = create_gsl_vector(source_data)
    else:
        destination = create_gsl_vector(destination_data)

    gsl.gsl_vector_memcpy(destination.vector, source.vector)

    return destination.tolist()

def verify_copy(source_data, copied_data):
    for i in range(len(source_data)):
        if fabs(source_data[i] - copied_data[i]) > 1e-10:
