def copy_matrix_gsl(source, destination):
    rows = len(source)
    cols = len(source[0])

    source_array = (ctypes.c_double * (rows * cols))()\    for i in range(rows):
        for j in range(cols):
            source_array[i * cols + j] = source[i][j]

    destination_array = (ctypes.c_double * (rows * cols))()
    for i in range(rows):
        for j in range(cols):
            destination_array[i * cols + j] = 0.0

    gslcblas.dcopy(ctypes.byref(ctypes.c_int(rows * cols)), source_array, ctypes.byref(ctypes.c_int(1)), destination_array, ctypes.byref(ctypes.c_int(1)))

    for i in range(rows):
        for j in range(cols):
            destination[i][j] = destination_array[i * cols + j]

    return destination

