PermType = ctypes.c_void_p

def gsl_permutation_alloc(n):
    return gsl.gsl_permutation_alloc(n)

def gsl_permutation_free(p):
    gsl.gsl_permutation_free(p)

def gsl_permutation_memcpy(dest, src):
    gsl.gsl_permutation_memcpy(dest, src)

def gsl_permutation_fwrite(stream, p):
    return gsl.gsl_permutation_fwrite(stream, p)

def gsl_permutation_fread(stream, p):
    return gsl.gsl_permutation_fread(stream, p)

# Write and read permutation to/from file
def write_and_read_permutation(perm_list):
    n = len(perm_list)
    perm = gsl_permutation_alloc(n)
    try:
        for i, value in enumerate(perm_list):
            ctypes.memmove(ctypes.addressof(perm.perm.contents) + i * ctypes.sizeof(ctypes.c_size_t), ctypes.byref(ctypes.c_size_t(value)), ctypes.sizeof(ctypes.c_size_t))

        # Write permutation to file
        with open("temp_perm.bin", "wb") as f:
            gsl_permutation_fwrite(f, perm)

        # Read permutation from file
        perm_read = gsl_permutation_alloc(n)
        try:
            with open("temp_perm.bin", "rb") as f:
                gsl_permutation_fread(f, perm_read)

            # Convert the read permutation to a list
            read_list = [ctypes.c_size_t.from_buffer_copy(ctypes.addressof(perm_read.perm.contents) + i * ctypes.sizeof(ctypes.c_size_t)).value for i in range(n)]
        finally:
            gsl_permutation_free(perm_read)
    finally:
        gsl_permutation_free(perm)

    return read_list

