class GSLMatrix:
    def __init__(self, matrix):
        self.matrix = gsl.gsl_matrix_alloc(len(matrix), len(matrix[0]))
        for i in range(len(matrix)):
            for j in range(len(matrix[0])):
                gsl.gsl_matrix_set(self.matrix, i, j, matrix[i][j])

    def extract(self):
        result = [[0] * self.matrix.tda for _ in range(self.matrix.size1)]
        for i in range(self.matrix.size1):
            for j in range(self.matrix.size2):
                result[i][j] = gsl.gsl_matrix_get(self.matrix, i, j)
        return result

    def __del__(self):
        gsl.gsl_matrix_free(self.matrix)

def apply_givens_qr(Q, R, i, j, c, s):
    Q_obj = GSLMatrix(Q)
    R_obj = GSLMatrix(R)
    gsl.apply_givens_qr(len(Q), len(Q[0]), Q_obj.matrix, R_obj.matrix, i, j, c, s)
    return Q_obj.extract(), R_obj.extract()

