import ctypes

class GSLMatrix:
    def __init__(self, matrix):
        self.matrix = matrix
        self.rows = len(matrix)
        self.cols = len(matrix[0]) if self.rows > 0 else 0

    def to_gsl(self):
        libgslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
        data_type = (ctypes.c_double * self.rows) * self.cols
        c_matrix = data_type(*([item for sublist in self.matrix for item in sublist]))
        gsl_matrix = gsl.gsl_matrix_alloc(self.rows, self.cols)
        for i in range(self.rows):
            for j in range(self.cols):
                gsl.gsl_matrix_set(gsl_matrix, i, j, c_matrix[i * self.cols + j])
        return gsl_matrix

    def from_gsl(self, gsl_matrix):
        rows = gsl.gsl_matrix_rows(gsl_matrix)
        cols = gsl.gsl_matrix_cols(gsl_matrix)
        data_type = (ctypes.c_double * rows) * cols
        c_matrix = (data_type * 1)()[:]
        for i in range(rows):
            for j in range(cols):
                c_matrix[i * cols + j] = gsl.gsl_matrix_get(gsl_matrix, i, j)
        matrix = [[c_matrix[i * cols + j] for j in range(cols)] for i in range(rows)]
        return matrix

