def perform_weighted_least_squares(x, y, weights=None):
    if len(x) != len(y):
        raise ValueError("x and y must have the same length")
    if weights is not None:
        if len(weights) != len(x):
            raise ValueError("weights must have the same length as x and y")

    n = len(x)
    if weights is None:
        weights = [1.0] * n

    gsl_vector_x = gsl.gsl_vector_alloc(n)
    for i in range(n):
        gsl.gsl_vector_set(gsl_vector_x, i, x[i])

    gsl_vector_y = gsl.gsl_vector_alloc(n)
    for i in range(n):
        gsl.gsl_vector_set(gsl_vector_y, i, y[i])

    gsl_vector_weights = gsl.gsl_vector_alloc(n)
    for i in range(n):
        gsl.gsl_vector_set(gsl_vector_weights, i, weights[i])

    workspace = gsl.gsl_bspline_workspace_alloc(4, 10)  # Example: 4 basis functions and 9 intervals
    gsl.gsl_bspline_wlssolve(workspace, gsl_vector_x, gsl_vector_y, gsl_vector_weights)

    coefficients = [gsl.gsl_vector_get(gsl.bspline_workspace_get_c(workspace), i) for i in range(4)]
    chi_squared = gsl.gsl_blas_ddot(gsl_vector_y, gsl_vector_y) - sum(coefficients[i] * sum(weights[j] * x[j]**i for j in range(n)) for i in range(4))

    gsl.gsl_vector_free(gsl_vector_x)
    gsl.gsl_vector_free(gsl_vector_y)
    gsl.gsl_vector_free(gsl_vector_weights)
    gsl.gsl_bspline_workspace_free(workspace)

    return (coefficients, chi_squared)

