import json
def load_gsl_linalg_functions():
    ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    return gsl

def matrix_to_gsl(matrix, M, N):
    gsl_matrix = gsl.matrix_view_array((M * N) * ctypes.c_double.from_buffer_copy(ctypes.create_string_buffer((M * N) * 8)), M, N)
    for i in range(M):
        for j in range(N):
            gsl_matrix.data[i * N + j] = matrix[i][j]
    return gsl_matrix

def vector_to_gsl(vector, N):
    gsl_vector = gsl.vector_view_array((N) * ctypes.c_double.from_buffer_copy(ctypes.create_string_buffer((N) * 8)), N)
    for i in range(N):
        gsl_vector.data[i] = vector[i]
    return gsl_vector

def gsl_matrix_to_list(gsl_matrix, M, N):
    matrix = [[0.0 for _ in range(N)] for _ in range(M)]
    for i in range(M):
        for j in range(N):
            matrix[i][j] = gsl_matrix.data[i * N + j]
    return matrix

def gsl_vector_to_list(gsl_vector, N):
    vector = [0.0 for _ in range(N)]
    for i in range(N):
        vector[i] = gsl_vector.data[i]
    return vector

def ql_decomposition_and_unpack(A, tau):
    M, N = len(A), len(A[0])
    A_gsl = matrix_to_gsl(A, M, N)
    tau_gsl = vector_to_gsl(tau, N)
    gsl = load_gsl_linalg_functions()
    gsl.gsl_linalg_QL_decomp.argtypes = [ctypes.POINTER(gsl_matrix), ctypes.POINTER(ctypes.c_double)]
    gsl.gsl_linalg_QL_decomp.restype = ctypes.c_int
    result = gsl.gsl_linalg_QL_decomp(A_gsl, tau_gsl)
    if result != 0:
        raise Exception("QL decomposition failed")
    Q = gsl_matrix_to_list(gsl.gsl_matrix_alloc(M, M), M, M)
    L = gsl_matrix_to_list(gsl.gsl_matrix_alloc(N, N), N, N)
    for i in range(M):
        for j in range(min(i + 1, N)):
            L[i][j] = A_gsl.data[i * N + j]
    for k in range(0, M):
        Q[k][k] = 1.0
    for k in range(N - 1, -1, -1):
        temp = Q[k][k]
        Q[k][k] = tau_gsl.data[k]
        tau_gsl.data[k] = temp
        for j in range(k + 1, N):
            sum = 0.0
            for i in range(k + 1, M):
                sum += Q[i][k] * A_gsl.data[i * N + j]
            for i in range(k + 1, M):
                Q[i][j] -= sum * A_gsl.data[i * N + k]
    return [Q, L]
def main():
    A = [[2.0, 1.0], [4.0, 3.0]]
    tau = [0.0, 0.0]
    result = ql_decomposition_and_unpack(A, tau)
    print(json.dumps(result))
if __name__ == "__main__":
    main()

