class RingBuf(ctypes.Structure):
    _fields_ = [("data", ctypes.POINTER(ctypes.c_double)),
                ("size", ctypes.c_size_t),
                ("head", ctypes.c_size_t),
                ("tail", ctypes.c_size_t)]

def initialize_ringbuf(size: int) -> ctypes.POINTER(RingBuf):
    func = gsl.gsl_ringbuffer_alloc
    func.argtypes = [ctypes.c_size_t]
    func.restype = ctypes.POINTER(RingBuf)
    return func(size)

def insert_into_ringbuf(ringbuf: ctypes.POINTER(RingBuf), values: list) -> None:
    func = gsl.gsl_ringbuffer_push_back
    func.argtypes = [ctypes.POINTER(RingBuf), ctypes.c_double]
    for value in values:
        if ringbuf.contents.tail - ringbuf.contents.head < ringbuf.contents.size:
            func(ringbuf, ctypes.c_double(value))
        else:
            raise ValueError("Ring buffer is full")

def copy_ringbuf_to_list(ringbuf: ctypes.POINTER(RingBuf)) -> list:
    result = []
    for i in range(ringbuf.contents.tail - ringbuf.contents.head):
        func = gsl.gsl_ringbuffer_get
        func.argtypes = [ctypes.POINTER(RingBuf), ctypes.c_size_t]
        func.restype = ctypes.c_double
        result.append(func(ringbuf, ringbuf.contents.head + i))
    return result

def main(values: list) -> list:
    ringbuf = initialize_ringbuf(len(values))
    insert_into_ringbuf(ringbuf, values)
    return copy_ringbuf_to_list(ringbuf)

