class gsl_permutation(ctypes.Structure):
    _fields_ = ["data", "size"]

    def __init__(self, size=0):
        super().__init__()
        self.size = size
        self.data = (ctypes.c_size_t * size)()

    @staticmethod
    def create(size):
        perm = gsl_permutation(size)
        if gsl.gsl_permutation_alloc(ctypes.byref(perm)) != GSL_SUCCESS:
            raise RuntimeError("Failed to allocate permutation")
        return perm

    @staticmethod
    def free(perm):
        gsl.gsl_permutation_free(ctypes.byref(perm))

def permutation_inverse(permutation):
    input_perm = gsl_permutation.create(len(permutation))
    for i, value in enumerate(permutation):
        input_perm.data[i] = value

    output_perm = gsl_permutation.create(len(permutation))

    if gsl.gsl_permutation_inverse(ctypes.byref(output_perm), ctypes.byref(input_perm)) != GSL_SUCCESS:
        raise RuntimeError("Failed to compute permutation inverse")

    result = [output_perm.data[i] for i in range(len(output_perm.data))]

    gsl_permutation.free(input_perm)
    gsl_permutation.free(output_perm)

    return result

