class GSLBlock:
    def __init__(self, data):
        self.data = data
        self.block_ptr = self._initialize_block(data)

    def _initialize_block(self, data):
        try:
            # Create a ctypes array from the input data
            c_data = (ctypes.c_double * len(data))(*data)
            # Call the initialize_gsl_block function from GSL
            block_ptr = gsl.gsl_block_alloc(len(data))
            if block_ptr is None:
                return None
            block_ptr.data = ctypes.cast(c_data, ctypes.POINTER(ctypes.c_double))
            return block_ptr
        except Exception as e:
            print(f"Error initializing GSL block: {e}")
            return None

    def __del__(self):
        if self.block_ptr is not None:
            gsl.gsl_block_free(self.block_ptr)

