class gsl_function(ctypes.Structure):
    _fields_ = ["function", "params"]

def func_wrapper(x, params):
    py_func = params[0]
    return py_func(x)

compute_integral = gsl.gsl_integration_romberg
compute_integral.argtypes = [ctypes.POINTER(gsl_function), ctypes.c_double, ctypes.c_double, ctypes.c_double, ctypes.c_double, ctypes.c_size_t]
compute_integral.restype = ctypes.c_int

def compute_integral_wrapper(py_func, a, b, epsabs, epsrel, n):
    func = gsl_function()
    func.function = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double, ctypes.POINTER(ctypes.py_object))(func_wrapper)
    func.params = ctypes.py_object((py_func, None))

    result = ctypes.c_double(0.0)
    abserr = ctypes.c_double(0.0)
    neval = ctypes.c_size_t(0)
    workspace = gsl.gsl_integration_romberg_alloc(n)
    status = compute_integral(ctypes.byref(func), a, b, epsabs, epsrel, n, ctypes.byref(result), ctypes.byref(abserr), ctypes.byref(neval))

    if status != 0:
        raise Exception(f"GSL error: {status}")

    gsl.gsl_integration_romberg_free(workspace)
    return result.value, neval.value

