        raise ValueError("yrange must be a list of doubles with at least two elements")
    if any(xrange[i] >= xrange[i+1] for i in range(len(xrange)-1)):
        raise ValueError("xrange must be in increasing order")
    if any(yrange[i] >= yrange[i+1] for i in range(len(yrange)-1)):
        raise ValueError("yrange must be in increasing order")
    xrange_ptr = (ctypes.c_double * len(xrange))(*xrange)
