gsl.negative_binomial_cdf_Q.argtypes = [ctypes.c_uint, ctypes.c_double, ctypes.c_double]
gsl.negative_binomial_cdf_Q.restype = ctypes.c_double

def negative_binomial_cdf(k, p, n):
    if k < 0 or p <= 0 or p >= 1:
        raise ValueError("Invalid input values")
    return gsl.negative_binomial_cdf_P(k, p, n), gsl.negative_binomial_cdf_Q(k, p, n)

# Test cases
